public interface PumpkinDrive extends Subsystem {
  // state
  Pose2d getPose();
  Rotation2d getHeading();                      // blue-origin field heading
  ChassisSpeeds getRobotRelativeSpeeds();
  ChassisSpeeds getFieldRelativeSpeeds();
  SwerveModuleState[] getModuleStates();        // length 0 when !geometry().isHolonomic()
  SwerveModulePosition[] getModulePositions();
  DriveGeometry geometry();                     // module locations | trackwidth, driveBaseRadius, isHolonomic
  DriveLimits limits();                         // maxLinearVel, maxAngularVel, maxLinearAccel, slipForceNewtons

  // THE funnel: every command, auto, and driver input goes through here
  void driveRobotRelative(ChassisSpeeds speeds, @Nullable DriveFeedforwards ff);
  default void driveRobotRelative(ChassisSpeeds s) { driveRobotRelative(s, null); }
  void stop();
  void brake();                                 // X-lock (swerve) / neutral-brake (diff)

  // pose
  void resetPose(Pose2d pose);
  void addVisionMeasurement(Pose2d pose, double timestampSeconds, Matrix<N3,N1> stdDevs);

  // characterization hooks (implemented once per backend, ~10 lines each)
  void runCharacterization(double volts);
  double[] getWheelRadiusCharacterizationPositions();   // radians per module
  double getFFCharacterizationVelocity();               // rad/s, mean

  // factories
  static PumpkinDrive from(com.ctre.phoenix6.swerve.SwerveDrivetrain<?,?,?> ctre, DriveGeometry g);
  static PumpkinDrive fromYagsl(java.io.File deploySwerveDir);
  static PumpkinDrive fromAdvantageKit(AdvantageKitDriveAdapter a);
  static PumpkinDrive swerve(HandRolledSwerveConfig cfg);
  static PumpkinDrive differential(DifferentialConfig cfg);
  static PumpkinDrive mecanum(MecanumConfig cfg);
}

public final class PumpkinAuto {
  public static PumpkinAuto of(PumpkinDrive drive);
  public PumpkinAuto withPathPlanner();                       // RobotConfig.fromGUISettings() + AutoBuilder.configure(...)
  public PumpkinAuto withPathPlanner(RobotConfig cfg, PIDConstants translation, PIDConstants rotation);
  public PumpkinAuto withChoreo(String trajectoryDir);        // builds a ChoreoLib AutoFactory on the same drive
  public PumpkinAuto withPathfinding();                       // LocalADStar, or LocalADStarAK when replay is enabled
  public SendableChooser<Command> chooser();
  public Command path(String name);                           // resolves from PathPlanner or Choreo transparently
  public Command driveToPose(Pose2d target, PathConstraints c);
  // built once, used everywhere:
  public static BooleanSupplier shouldFlip();                 // DriverStation.getAlliance().orElse(Blue) == Red
}

public enum TractionMode { NONE, SLEW_RATE, SETPOINT_GENERATOR }

public final class TractionLayer {
  public TractionLayer(RobotConfig cfg, double maxModuleRotationVelRadPerSec);
  public ChassisSpeeds apply(ChassisSpeeds desired, double loopSeconds);   // wraps SwerveSetpointGenerator.generateSetpoint
  public DriveFeedforwards lastFeedforwards();
}
// usage: PumpkinDriveConfig.traction(TractionMode.SETPOINT_GENERATOR)
// CRITICAL: the layer owns discretization. PumpkinDrive must never call ChassisSpeeds.discretize
// when TractionMode.SETPOINT_GENERATOR is active — PathPlanner discretizes internally.

public final class PumpkinCharacterization {
  public static Command feedforward(PumpkinDrive d);   // 2s orient, 0.1 V/s ramp, least-squares kS/kV, prints + logs
  public static Command wheelRadius(PumpkinDrive d);   // 0.05 rad/s^2 to 0.25 rad/s spin; r = gyroDelta*driveBaseRadius/meanWheelDelta
  public static Command slipCurrent(PumpkinDrive d);   // wall-push voltage ramp; reports stator A at velocity break
  public static Command momentOfInertia(PumpkinDrive d);
  public static Command sysIdAll(PumpkinDrive d);      // quasistatic fwd/rev + dynamic fwd/rev, WPILog + hoot
  public static void writeResults(Path deployJson);    // -> deploy/pumpkin/drive_characterization.json
}

// Shipped defaults keyed by motor + module preset, used as starting points only:
public enum DrivePreset { KRAKEN_X60_MK4I_L2, KRAKEN_X60_MK4I_L3, FALCON500_MK4I_L2,
                          NEO_VORTEX_MAXSWERVE_13T, NEO_MAXSWERVE_13T, KRAKEN_X44_MK5I_R2 }

public final class SkidDetector {
  public SkidDetector(DriveGeometry geometry);
  /** Compare each module's measured translational velocity against the gyro-derived
   *  rigid-body prediction; the spread (std dev of the residuals) is the skid ratio. */
  public SkidReport update(SwerveModuleState[] measured, double gyroOmegaRadPerSec);
  public record SkidReport(double skidRatio, boolean skidding, int worstModuleIndex) {}
}
public final class OdometryTrust {
  public Matrix<N3,N1> wheelStdDevs(SkidReport r);   // inflate on skid
  public Matrix<N3,N1> visionStdDevs(SkidReport r, VisionObservation o);
}

public final class DriveInputStream implements Supplier<ChassisSpeeds> {
  public static DriveInputStream of(PumpkinDrive d, DoubleSupplier x, DoubleSupplier y);
  public DriveInputStream withRotationAxis(DoubleSupplier omega);
  public DriveInputStream withHeadingAxis(DoubleSupplier hx, DoubleSupplier hy);
  public DriveInputStream deadband(double d);                       // uses MathUtil.applyDeadband 2D variant (new 2026)
  public DriveInputStream scaleTranslation(double s);
  public DriveInputStream scaleRotation(double s);
  public DriveInputStream expo(double translationPow, double rotationPow);  // MathUtil.copySignPow
  public DriveInputStream robotRelative(BooleanSupplier b);
  public DriveInputStream allianceRelative(BooleanSupplier b);      // the alliance-flip trap, solved once
  public DriveInputStream headingLock(BooleanSupplier b);
  public DriveInputStream aimAt(Supplier<Translation2d> target, BooleanSupplier b);
  public DriveInputStream driveToPose(Supplier<Pose2d> p, BooleanSupplier b);
  public DriveInputStream slewRate(double linearMpsPerSec, double angularRadPerSecSq);
  public Command asCommand();
  @Override public ChassisSpeeds get();
}
