public final class AlliancePerspective {
  /** Call from robotPeriodic; applies Rotation2d.kZero on blue, Rotation2d.k180deg on red. */
  public static void update(PumpkinDrive drive);
  public static boolean isRed();
  public static Pose2d flipIfRed(Pose2d bluePose);
  public static Rotation2d operatorForward();
  /** Driver-facing 'zero the gyro' — resets the OPERATOR perspective, never the pose. */
  public static Command zeroDriverHeading(PumpkinDrive drive);
  /** Absolute, blue-origin. Used by autos and vision only. */
  public static void resetFieldRotation(PumpkinDrive drive, Rotation2d blueHeading);
}

public record DifferentialConfig(
    DifferentialDriveKinematics kinematics,
    MotorGroup left, MotorGroup right,
    GyroIO gyro,
    double wheelRadiusMeters, double gearReduction,
    SimpleMotorFeedforward feedforward,
    PIDConstants velocityGains) {}

public final class DifferentialBackend implements PumpkinDrive {
  // driveRobotRelative -> kinematics.toWheelSpeeds(speeds) -> per-side velocity PID + FF
  // path following via LTVUnicycleController(0.02) — NOT RamseteController (deprecated for removal)
  // getModuleStates() returns new SwerveModuleState[0]; geometry().isHolonomic() == false
}
// PumpkinAuto must select the Consumer<ChassisSpeeds> AutoBuilder.configure overload for
// non-holonomic drives and RobotConfig(massKG, MOI, moduleConfig, trackwidthMeters).

public final class PumpkinTuner {
  public static TunableLoop drive(PumpkinDrive d);      // exposes kS,kV,kA,kP,kD as NT-tunable
  public static TunableLoop steer(PumpkinDrive d);
  public static TunableLoop heading(PumpkinDrive d);
  public interface TunableLoop {
    Command stepResponse(double magnitude);   // logs setpoint/measured/error/output as struct arrays
    Command sineSweep(double lowHz, double highHz);
    TuningVerdict critique();                 // 'overshoot 18% -> lower kP or add kD'; 'steady-state offset -> kS too low'
    void publish(String ntTable);             // AdvantageScope-ready, unit-tagged (AdvantageKit 2026 unit metadata)
    void writeToDeploy();                     // persists to deploy/pumpkin/gains.json — survives redeploy
  }
}

public record PumpkinDriveConfig(
    OdometryMode odometry,        // NATIVE_250HZ (CANivore+Pro), THREADED_100HZ, LOOP_50HZ
    TractionMode traction,
    DriveSimBackend simBackend,   // MAPLE (default), CTRE_NATIVE, WPILIB_IDEAL
    boolean enableReplay,         // wires AdvantageKit IOInputs + LocalADStarAK
    boolean enableSkidDetection) {
  public static PumpkinDriveConfig competition();   // 250Hz + SETPOINT_GENERATOR + MAPLE + replay + skid
  public static PumpkinDriveConfig rookie();        // THREADED_100HZ + NONE + MAPLE + replay off
}
